import React from 'react';
import { useVoiceToText } from '../../hooks/useVoiceToText';

export default function DictationButton({ onResult, className = "" }) {
  const { isListening, startListening, stopListening, isSupported, error } = useVoiceToText();

  if (!isSupported) {
    return null; // Omit button if browser doesn't support Web Speech API
  }

  const handleToggle = (e) => {
    e.preventDefault();
    if (isListening) {
      stopListening();
    } else {
      startListening(onResult);
    }
  };

  return (
    <button
      onClick={handleToggle}
      title={isListening ? "Zakończ dyktowanie" : "Podyktuj tekst (głos)"}
      className={`flex items-center justify-center rounded-full p-2 transition-all ${
        isListening 
          ? 'bg-red-500 text-white animate-pulse shadow-md shadow-red-500/50' 
          : 'bg-slate-100 text-slate-500 hover:bg-indigo-50 hover:text-indigo-600'
      } ${className}`}
    >
      <i className={`ph ${isListening ? 'ph-microphone-stage' : 'ph-microphone'} text-xl`}></i>
    </button>
  );
}
